import os,glob,re,json

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G=load()

# Demo 1
demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']

# Test input
test_in = G['Test input']

print("Demo input shape:", len(demo_in), "x", len(demo_in[0]))
print("Demo output shape:", len(demo_out), "x", len(demo_out[0]))
print("Test input shape:", len(test_in), "x", len(test_in[0]))

# Analyze the rule
# Pattern: 4s that are BETWEEN 9s horizontally or vertically convert to 2s
# Let me check this hypothesis

def check_horizontal_between(grid, row_idx, col):
    """Check if cell at (row_idx, col) is horizontally between two 9s"""
    # Find 9s in this row
    nine_cols = [c for c in range(len(grid[row_idx])) if grid[row_idx][c] == 9]
    # Check if this col is between two 9s
    for i in range(len(nine_cols)-1):
        if nine_cols[i] < col < nine_cols[i+1]:
            return True
    return False

def check_vertical_between(grid, col_idx, row):
    """Check if cell at (row, col_idx) is vertically between two 9s"""
    nine_rows = [r for r in range(len(grid)) if grid[r][col_idx] == 9]
    for i in range(len(nine_rows)-1):
        if nine_rows[i] < row < nine_rows[i+1]:
            return True
    return False

# Apply rule to demo 1
predicted_demo_out = []
for r in range(len(demo_in)):
    row_pred = []
    for c in range(len(demo_in[0])):
        val = demo_in[r][c]
        if val == 4:
            h_between = check_horizontal_between(demo_in, r, c)
            v_between = check_vertical_between(demo_in, c, r)
            if h_between or v_between:
                row_pred.append(2)
            else:
                row_pred.append(val)
        else:
            row_pred.append(val)
    predicted_demo_out.append(row_pred)

# Compare
correct = sum(1 for r in range(len(demo_in)) for c in range(len(demo_in[0])) 
              if predicted_demo_out[r][c] == demo_out[r][c])
total = len(demo_in) * len(demo_in[0])
print(f"Rule correctness: {correct}/{total} = {correct/total:.2%}")

# Show mismatches
for r in range(len(demo_in)):
    for c in range(len(demo_in[0])):
        if predicted_demo_out[r][c] != demo_out[r][c]:
            print(f"Mismatch at ({r},{c}): pred={predicted_demo_out[r][c]}, actual={demo_out[r][c]}")

import os,glob,re,json

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G=load()
demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']
test_in = G['Test input']

# New hypothesis: Count number of 9s in each row/column
# Convert 4s to 2s only in rows/cols with >= 4 nines AND with regular-ish spacing

def has_9s_in_row(grid, row_idx):
    return sum(1 for c in range(len(grid[row_idx])) if grid[row_idx][c] == 9)

def has_9s_in_col(grid, col_idx):
    return sum(1 for r in range(len(grid)) if grid[r][col_idx] == 9)

def gap_variance(row_data):
    """Calculate variance in gaps between consecutive nines"""
    if len(row_data) < 2:
        return 0
    gaps = [row_data[i+1]-row_data[i]-1 for i in range(len(row_data)-1)]
    if len(gaps) < 2:
        return 0
    mean = sum(gaps)/len(gaps)
    return sum((g-m)**2 for g,m in zip(gaps,mean))/len(gaps)

# Try new rule: 
# A 4 converts to 2 if:
#   - it's in a row with variance < 3 in gap distances, AND the row has nines
#   - OR it's in a col with variance < 3 in gap distances, AND the col has nines

def new_rule_predict(grid):
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    # Check rows
    for r in range(len(grid)):
        nines = [c for c in range(len(grid[r])) if grid[r][c] == 9]
        if len(nines) >= 2:
            var = gap_variance(nines)
            # For row, a run of 4s between two 9s converts if variance is low
            for i in range(len(nines)-1):
                left_9 = nines[i]
                right_9 = nines[i+1]
                for c in range(left_9+1, right_9):
                    if grid[r][c] == 4:
                        # Also check if row overall has low variance
                        if var < 4:  # heuristic
                            result[r][c] = 2

    # Check cols
    for c in range(len(grid[0])):
        nines = [r for r in range(len(grid)) if grid[r][c] == 9]
        if len(nines) >= 2:
            var = gap_variance(nines)
            for i in range(len(nines)-1):
                top_9 = nines[i]
                bot_9 = nines[i+1]
                for r in range(top_9+1, bot_9):
                    if grid[r][c] == 4:
                        if var < 4:
                            result[r][c] = 2

    return result

pred = new_rule_predict(demo_in)
correct = sum(1 for r in range(len(demo_in)) for c in range(len(demo_in[0])) 
              if pred[r][c] == demo_out[r][c])
print(f"New rule correctness: {correct}/{len(demo_in)*len(demo_in[0])} = {correct/(len(demo_in)*len(demo_in[0])):.2%}")

for r in range(len(demo_in)):
    for c in range(len(demo_in[0])):
        if pred[r][c] != demo_out[r][c]:
            print(f"Mismatch ({r},{c}): pred={pred[r][c]}, actual={demo_out[r][c]}")

import os,glob,re,json,math

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G=load()
demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']

# New hypothesis: A row has "regular spacing" if variance of gaps is low
def gap_variance(nine_positions):
    """Calculate variance in gaps between consecutive nines"""
    if len(nine_positions) < 2:
        return float('inf')
    gaps = [nine_positions[i+1]-nine_positions[i]-1 for i in range(len(nine_positions)-1)]
    if len(gaps) < 2:
        return 0  # Only one gap, define as regular
    mean = sum(gaps)/len(gaps)
    var = sum((g-mean)**2 for g in gaps)/len(gaps)
    return var

def new_rule_predict(grid):
